/*
 * A210033  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A210034; see the Formula section.
 * https://oeis.org/A210033
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is the nth coefficient in the flattened list of the
 *            polynomials u(n,x) generated by u(1,x)=1, v(1,x)=1,
 *            u(n,x)=u(n-1,x)+v(n-1,x)+1, v(n,x)=u(n-1,x)+x*v(n-1,x)+1
 * Range:     u8 n <= 38, u16 n <= 67, u32 n <= 67, u64 n <= 67, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static idx_t computed_rows = 0;   /* highest row computed so far */
    static seq_t *coeffs = NULL;      /* flattened coefficients of all rows */
    static size_t coeffs_len = 0;     /* number of coefficients stored */
    static size_t coeffs_cap = 0;     /* capacity of coeffs array */

    static seq_t *u = NULL;           /* current u polynomial coefficients */
    static size_t u_len = 0;          /* length of u */
    static seq_t *v = NULL;           /* current v polynomial coefficients */
    static size_t v_len = 0;          /* length of v */

    if (n == 0)
        return (seq_t)0;              /* undefined, but return 0 for safety */

    /* Grow until the n‑th coefficient is available. */
    while (coeffs_len < n)
    {
        /* ---- initial row 1 ------------------------------------------------ */
        if (computed_rows == 0)
        {
            u_len = 1;
            v_len = 1;
            u = (seq_t *)malloc(sizeof(seq_t));
            v = (seq_t *)malloc(sizeof(seq_t));
            u[0] = v[0] = (seq_t)1;

            /* store first coefficient u(1)[0] */
            if (coeffs_cap == 0)
            {
                coeffs = (seq_t *)malloc(sizeof(seq_t));
                coeffs_cap = 1;
            }
            coeffs[coeffs_len++] = u[0];

            computed_rows = 1;
            continue;
        }

        /* ---- compute next row ------------------------------------------------ */
        idx_t next_row = computed_rows + (idx_t)1;
        size_t new_u_len = (next_row == (idx_t)1) ? (size_t)1 : (size_t)(next_row - (idx_t)1);
        size_t new_v_len = (size_t)next_row;

        /* Allocate new coefficient arrays */
        seq_t *new_u = (seq_t *)malloc(new_u_len * sizeof(seq_t));
        seq_t *new_v = (seq_t *)malloc(new_v_len * sizeof(seq_t));

        /* u(new) = u + v + 1 */
        new_u[0] = u[0] + v[0] + (seq_t)1;
        for (size_t i = 1; i < new_u_len; ++i)
        {
            seq_t a = (i < u_len) ? u[i] : (seq_t)0;
            seq_t b = (i < v_len) ? v[i] : (seq_t)0;
            new_u[i] = a + b;
        }

        /* v(new) = u + x*v + 1 */
        new_v[0] = u[0] + (seq_t)1;
        for (size_t i = 1; i < new_v_len; ++i)
        {
            seq_t a = (i < u_len) ? u[i] : (seq_t)0;
            seq_t b = ((i - 1) < v_len) ? v[i - 1] : (seq_t)0;
            new_v[i] = a + b;
        }

        /* Ensure capacity for new coefficients */
        if (coeffs_len + new_u_len > coeffs_cap)
        {
            size_t new_cap = (coeffs_cap == 0) ? 1 : coeffs_cap;
            while (coeffs_len + new_u_len > new_cap)
                new_cap <<= 1;
            seq_t *tmp = (seq_t *)realloc(coeffs, new_cap * sizeof(seq_t));
            if (!tmp) abort();          /* out of memory */
            coeffs = tmp;
            coeffs_cap = new_cap;
        }

        for (size_t i = 0; i < new_u_len; ++i)
            coeffs[coeffs_len++] = new_u[i];

        /* free old arrays and update state */
        free(u);
        free(v);
        u = new_u;
        v = new_v;
        u_len = new_u_len;
        v_len = new_v_len;
        computed_rows = next_row;
    }

    return coeffs[n - (idx_t)1];
}
